<?php
function e($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function redirect(string $url): never { header('Location: '.$url); exit; }
function csrf_token(): string { return $_SESSION['_csrf'] ??= bin2hex(random_bytes(24)); }
function csrf_field(): string { return '<input type="hidden" name="_csrf" value="'.e(csrf_token()).'">'; }
function check_csrf(): void { if (!hash_equals($_SESSION['_csrf'] ?? '', $_POST['_csrf'] ?? '')) { http_response_code(419); exit('Invalid form token. Refresh and try again.'); } }
function user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): array { $u=user(); if (!$u) redirect('?page=login'); return $u; }
function flash(?string $message=null): ?string { if ($message !== null) { $_SESSION['_flash']=$message; return null; } $m=$_SESSION['_flash']??null; unset($_SESSION['_flash']); return $m; }
function q(PDO $db, string $sql, array $params=[]): PDOStatement { $s=$db->prepare($sql); $s->execute($params); return $s; }
function one(PDO $db,string $sql,array $params=[]): ?array { $r=q($db,$sql,$params)->fetch(); return $r?:null; }
function all(PDO $db,string $sql,array $params=[]): array { return q($db,$sql,$params)->fetchAll(); }
function layout_start(string $title, ?array $u=null): void { $app='CMU LMS'; echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · '.e($app).'</title><style>'.css().'</style></head><body><header><a class="brand" href="?page=dashboard">CMU·LMS</a><nav>'; if($u){ echo '<span>'.e($u['name']??$u['id_number']).' · '.e(ucfirst($u['role'])).'</span><form method="post" class="inline">'.csrf_field().'<input type="hidden" name="action" value="logout"><button>Sign out</button></form>'; } echo '</nav></header><main>'; if($m=flash()) echo '<div class="flash">'.e($m).'</div>'; }
function layout_end(): void { echo '</main><footer>Central Mindanao University · CISC</footer></body></html>'; }
function css(): string { return 'body{margin:0;font-family:Arial,sans-serif;background:#f4f7f5;color:#163f36}header{background:#124b3f;color:#fff;padding:16px 5%;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:2}.brand{color:#fff;font-size:24px;font-weight:700;text-decoration:none}nav{display:flex;align-items:center;gap:16px}button,.button{background:#216a58;color:#fff;border:0;border-radius:7px;padding:10px 15px;cursor:pointer;text-decoration:none;font-weight:600}button.secondary,.button.secondary{background:#e5efea;color:#174e41}.inline{display:inline}main{max-width:1100px;margin:28px auto;padding:0 18px}.hero,.card{background:#fff;border:1px solid #d9e4df;border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:0 2px 8px #123f2d0d}.hero{background:#1c6654;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.muted{color:#60756e}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#e1f1e8;color:#1c6654;font-size:12px;font-weight:700}.danger{background:#fff0ee;color:#a2382d}.field{display:flex;flex-direction:column;gap:6px;margin:12px 0}.field input,.field textarea,.field select{padding:11px;border:1px solid #cbdad3;border-radius:8px;font-size:15px}.options label{display:block;border:1px solid #d4e2dc;border-radius:8px;padding:12px;margin:8px 0}.flash{background:#def4e7;border:1px solid #95caaa;border-radius:8px;padding:12px;margin-bottom:16px}.question{border-left:4px solid #216a58}.timer{font-size:20px;font-weight:700;color:#a33b2e}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #dce7e1}footer{text-align:center;color:#60756e;padding:30px}a{color:#1c6654}@media(max-width:650px){header{align-items:flex-start;gap:12px;flex-direction:column}nav{width:100%;justify-content:space-between}main{margin-top:16px;padding:0 10px}}'; }
